// path: memtrainer.cpp
// build: clang++ -std=c++17 -O2 memtrainer.cpp -o memtrainer
// run:   sudo ./memtrainer <pid>
// does: trainer — scan, narrow, write and freeze int32 values in a running process (macOS, arm64/x86_64)

#include <mach/mach.h>
#include <mach/mach_vm.h>
#include <unistd.h>

#include <atomic>
#include <chrono>
#include <csignal>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

static std::atomic<bool> g_stop{false};
static void onSigint(int) { g_stop = true; }

struct Region {
    mach_vm_address_t base;
    mach_vm_size_t size;
};

struct Trainer {
    task_t task = MACH_PORT_NULL;
    std::vector<mach_vm_address_t> hits;

    static constexpr mach_vm_size_t kChunk = 16ull * 1024 * 1024;

    bool attach(pid_t pid) {
        kern_return_t kr = task_for_pid(mach_task_self(), pid, &task);
        if (kr != KERN_SUCCESS) {
            std::fprintf(stderr, "task_for_pid(%d) failed: %s\n", pid, mach_error_string(kr));
            return false;
        }
        return true;
    }

    std::vector<Region> regions() const {
        std::vector<Region> out;
        mach_vm_address_t addr = 0;
        for (;;) {
            mach_vm_size_t size = 0;
            vm_region_basic_info_data_64_t info{};
            mach_msg_type_number_t count = VM_REGION_BASIC_INFO_COUNT_64;
            mach_port_t object = MACH_PORT_NULL;
            kern_return_t kr = mach_vm_region(task, &addr, &size, VM_REGION_BASIC_INFO_64,
                                              reinterpret_cast<vm_region_info_t>(&info), &count, &object);
            if (kr != KERN_SUCCESS) break;
            if (object != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), object);

            const vm_prot_t rw = VM_PROT_READ | VM_PROT_WRITE;
            if ((info.protection & rw) == rw) out.push_back({addr, size});
            addr += size;
        }
        return out;
    }

    bool read32(mach_vm_address_t addr, int32_t& out) const {
        mach_vm_size_t got = 0;
        kern_return_t kr = mach_vm_read_overwrite(task, addr, sizeof(out),
                                                  reinterpret_cast<mach_vm_address_t>(&out), &got);
        return kr == KERN_SUCCESS && got == sizeof(out);
    }

    bool write32(mach_vm_address_t addr, int32_t value) const {
        kern_return_t kr = mach_vm_write(task, addr, reinterpret_cast<vm_offset_t>(&value), sizeof(value));
        return kr == KERN_SUCCESS;
    }

    size_t firstScan(int32_t value) {
        hits.clear();
        std::vector<uint8_t> buf(kChunk);
        auto regs = regions();
        mach_vm_size_t total = 0;

        for (const auto& r : regs) {
            for (mach_vm_size_t off = 0; off < r.size; off += kChunk) {
                mach_vm_size_t len = std::min(kChunk, r.size - off);
                mach_vm_size_t got = 0;
                kern_return_t kr = mach_vm_read_overwrite(task, r.base + off, len,
                                                          reinterpret_cast<mach_vm_address_t>(buf.data()), &got);
                if (kr != KERN_SUCCESS || got < sizeof(int32_t)) continue;
                total += got;

                for (mach_vm_size_t i = 0; i + sizeof(int32_t) <= got; i += sizeof(int32_t)) {
                    int32_t v;
                    std::memcpy(&v, buf.data() + i, sizeof(v));
                    if (v == value) hits.push_back(r.base + off + i);
                }
            }
        }
        std::printf("scanned %zu regions, %.1f MB\n", regs.size(), total / (1024.0 * 1024.0));
        return hits.size();
    }

    size_t nextScan(int32_t value) {
        std::vector<mach_vm_address_t> kept;
        kept.reserve(hits.size());
        for (auto a : hits) {
            int32_t v;
            if (read32(a, v) && v == value) kept.push_back(a);
        }
        hits.swap(kept);
        return hits.size();
    }

    size_t writeAll(int32_t value) const {
        size_t ok = 0;
        for (auto a : hits)
            if (write32(a, value)) ++ok;
        return ok;
    }

    void list(size_t max) const {
        size_t n = std::min(max, hits.size());
        for (size_t i = 0; i < n; ++i) {
            int32_t v = 0;
            bool ok = read32(hits[i], v);
            std::printf("  [%zu] 0x%016llx = %s%d\n", i, (unsigned long long)hits[i], ok ? "" : "?", v);
        }
        if (hits.size() > n) std::printf("  ... %zu more\n", hits.size() - n);
    }

    void freeze(int32_t value, int intervalMs) const {
        g_stop = false;
        std::signal(SIGINT, onSigint);
        std::printf("freezing %zu address(es) at %d, ctrl-c to stop\n", hits.size(), value);
        while (!g_stop) {
            writeAll(value);
            std::this_thread::sleep_for(std::chrono::milliseconds(intervalMs));
        }
        std::signal(SIGINT, SIG_DFL);
        std::printf("\nfreeze stopped\n");
    }
};

static void help() {
    std::puts(
        "commands:\n"
        "  scan <int>          first scan for exact int32 value\n"
        "  next <int>          keep hits that now equal <int>\n"
        "  list [n]            show up to n hits (default 20)\n"
        "  write <int>         write <int> to all hits\n"
        "  set <hexaddr> <int> write <int> to one address\n"
        "  pick <index>        reduce hits to a single entry\n"
        "  freeze <int> [ms]   rewrite all hits every ms (default 100)\n"
        "  help | quit");
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: sudo %s <pid>\n", argv[0]);
        return 1;
    }
    if (geteuid() != 0) std::fprintf(stderr, "warning: not root, task_for_pid will likely fail\n");

    pid_t pid = static_cast<pid_t>(std::strtol(argv[1], nullptr, 10));
    Trainer t;
    if (!t.attach(pid)) return 1;
    std::printf("attached to pid %d\n", pid);
    help();

    std::string line;
    while (std::printf("> "), std::fflush(stdout), std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string cmd;
        if (!(in >> cmd)) continue;

        if (cmd == "quit" || cmd == "q") break;
        else if (cmd == "help") help();
        else if (cmd == "scan") {
            int32_t v; if (!(in >> v)) { std::puts("scan <int>"); continue; }
            std::printf("%zu hits\n", t.firstScan(v));
        } else if (cmd == "next") {
            int32_t v; if (!(in >> v)) { std::puts("next <int>"); continue; }
            std::printf("%zu hits\n", t.nextScan(v));
        } else if (cmd == "list") {
            size_t n = 20; in >> n;
            t.list(n);
        } else if (cmd == "write") {
            int32_t v; if (!(in >> v)) { std::puts("write <int>"); continue; }
            std::printf("wrote %zu/%zu\n", t.writeAll(v), t.hits.size());
        } else if (cmd == "set") {
            std::string hex; int32_t v;
            if (!(in >> hex >> v)) { std::puts("set <hexaddr> <int>"); continue; }
            auto a = static_cast<mach_vm_address_t>(std::strtoull(hex.c_str(), nullptr, 16));
            std::puts(t.write32(a, v) ? "ok" : "write failed");
        } else if (cmd == "pick") {
            size_t i; if (!(in >> i) || i >= t.hits.size()) { std::puts("pick <valid index>"); continue; }
            t.hits = {t.hits[i]};
            std::puts("1 hit");
        } else if (cmd == "freeze") {
            int32_t v; int ms = 100;
            if (!(in >> v)) { std::puts("freeze <int> [ms]"); continue; }
            in >> ms;
            if (t.hits.empty()) { std::puts("no hits"); continue; }
            t.freeze(v, ms > 0 ? ms : 100);
        } else {
            std::puts("unknown command, try help");
        }
    }

    mach_port_deallocate(mach_task_self(), t.task);
    return 0;
}
```

how it works: `task_for_pid` gets a Mach task port for the target, `mach_vm_region` walks its address space keeping only read+write regions, and `mach_vm_read_overwrite` pu
